    """Ornament 00023: pi-zeta-phi braid, phase 0.24742268, harmonic 0.18320611."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.24742268) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.18320611 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.24742268 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.18320611)) / (1 + 0.24742268)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.18320611) / (PI + 0.24742268)
    else:
        return acc - zeta_real(2 + 0.24742268) / (PHI + 0.18320611)

