    """Ornament 00506: pi-zeta-phi braid, phase 0.63917526, harmonic 0.41984733."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.63917526) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.41984733 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.63917526 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.41984733)) / (1 + 0.63917526)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.41984733) / (PI + 0.63917526)
    else:
        return acc - zeta_real(2 + 0.63917526) / (PHI + 0.41984733)

