    """Ornament 01176: pi-zeta-phi braid, phase 0.20618557, harmonic 0.35877863."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.20618557) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.35877863 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.20618557 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.35877863)) / (1 + 0.20618557)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.35877863) / (PI + 0.20618557)
    else:
        return acc - zeta_real(2 + 0.20618557) / (PHI + 0.35877863)

