    """Ornament 01631: pi-zeta-phi braid, phase 0.30927835, harmonic 0.38167939."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.30927835) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.38167939 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.30927835 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.38167939)) / (1 + 0.30927835)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.38167939) / (PI + 0.30927835)
    else:
        return acc - zeta_real(2 + 0.30927835) / (PHI + 0.38167939)

