    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.23711340) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.77099237 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.23711340 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.77099237)) / (1 + 0.23711340)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.77099237) / (PI + 0.23711340)
    else:
        return acc - zeta_real(2 + 0.23711340) / (PHI + 0.77099237)

