    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.06185567) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.58778626 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.06185567 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.58778626)) / (1 + 0.06185567)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.58778626) / (PI + 0.06185567)
    else:
        return acc - zeta_real(2 + 0.06185567) / (PHI + 0.58778626)

