    """Ornament 02782: pi-zeta-phi braid, phase 0.24742268, harmonic 0.54198473."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 7):
        angle = PI * (x + k*0.24742268) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.54198473 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.24742268 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.54198473)) / (1 + 0.24742268)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.54198473) / (PI + 0.24742268)
    else:
        return acc - zeta_real(2 + 0.24742268) / (PHI + 0.54198473)

