    """Ornament 02889: pi-zeta-phi braid, phase 0.43298969, harmonic 0.49618321."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.43298969) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.49618321 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.43298969 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.49618321)) / (1 + 0.43298969)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.49618321) / (PI + 0.43298969)
    else:
        return acc - zeta_real(2 + 0.43298969) / (PHI + 0.49618321)

