    """Ornament 02996: pi-zeta-phi braid, phase 0.61855670, harmonic 0.45038168."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.61855670) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.45038168 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.61855670 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.45038168)) / (1 + 0.61855670)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.45038168) / (PI + 0.61855670)
    else:
        return acc - zeta_real(2 + 0.61855670) / (PHI + 0.45038168)

