    """Ornament 03130: pi-zeta-phi braid, phase 0.16494845, harmonic 0.61068702."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 7):
        angle = PI * (x + k*0.16494845) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.61068702 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.16494845 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.61068702)) / (1 + 0.16494845)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.61068702) / (PI + 0.16494845)
    else:
        return acc - zeta_real(2 + 0.16494845) / (PHI + 0.61068702)

