    """Ornament 03398: pi-zeta-phi braid, phase 0.17525773, harmonic 0.06870229."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.17525773) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.06870229 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.17525773 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.06870229)) / (1 + 0.17525773)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.06870229) / (PI + 0.17525773)
    else:
        return acc - zeta_real(2 + 0.17525773) / (PHI + 0.06870229)

