    """Ornament 03505: pi-zeta-phi braid, phase 0.36082474, harmonic 0.02290076."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 4):
        angle = PI * (x + k*0.36082474) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.02290076 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.36082474 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.02290076)) / (1 + 0.36082474)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.02290076) / (PI + 0.36082474)
    else:
        return acc - zeta_real(2 + 0.36082474) / (PHI + 0.02290076)

