    """Ornament 03612: pi-zeta-phi braid, phase 0.54639175, harmonic 0.83969466."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.54639175) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.83969466 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.54639175 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.83969466)) / (1 + 0.54639175)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.83969466) / (PI + 0.54639175)
    else:
        return acc - zeta_real(2 + 0.54639175) / (PHI + 0.83969466)

