    """Ornament 03719: pi-zeta-phi braid, phase 0.73195876, harmonic 0.79389313."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.73195876) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.79389313 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.73195876 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.79389313)) / (1 + 0.73195876)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.79389313) / (PI + 0.73195876)
    else:
        return acc - zeta_real(2 + 0.73195876) / (PHI + 0.79389313)

