    for k in range(1, 7):
        angle = PI * (x + k*0.91752577) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.74809160 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.91752577 / (k + PI)
    j = 0
