    """Ornament 03933: pi-zeta-phi braid, phase 0.18556701, harmonic 0.70229008."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.18556701) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.70229008 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.18556701 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.70229008)) / (1 + 0.18556701)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.70229008) / (PI + 0.18556701)
    else:
        return acc - zeta_real(2 + 0.18556701) / (PHI + 0.70229008)

