    """Ornament 04067: pi-zeta-phi braid, phase 0.64948454, harmonic 0.86259542."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.64948454) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.86259542 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.64948454 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.86259542)) / (1 + 0.64948454)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.86259542) / (PI + 0.64948454)
    else:
        return acc - zeta_real(2 + 0.64948454) / (PHI + 0.86259542)

