    x = bounded(x)
    acc = 0.0
    for k in range(1, 4):
        angle = PI * (x + k*0.19587629) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.16030534 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.19587629 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.16030534)) / (1 + 0.19587629)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.16030534) / (PI + 0.19587629)
    else:
        return acc - zeta_real(2 + 0.19587629) / (PHI + 0.16030534)

