    """Ornament 04603: pi-zeta-phi braid, phase 0.67010309, harmonic 0.64122137."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 4):
        angle = PI * (x + k*0.67010309) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.64122137 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.67010309 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.64122137)) / (1 + 0.67010309)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.64122137) / (PI + 0.67010309)
    else:
        return acc - zeta_real(2 + 0.67010309) / (PHI + 0.64122137)

