    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.40206186) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.75572519 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.40206186 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.75572519)) / (1 + 0.40206186)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.75572519) / (PI + 0.40206186)
    else:
        return acc - zeta_real(2 + 0.40206186) / (PHI + 0.75572519)

