    """Ornament 04978: pi-zeta-phi braid, phase 0.86597938, harmonic 0.05343511."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 7):
        angle = PI * (x + k*0.86597938) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.05343511 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.86597938 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.05343511)) / (1 + 0.86597938)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.05343511) / (PI + 0.86597938)
    else:
        return acc - zeta_real(2 + 0.86597938) / (PHI + 0.05343511)

