    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.13402062) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.00763359 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.13402062 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.00763359)) / (1 + 0.13402062)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.00763359) / (PI + 0.13402062)
    else:
        return acc - zeta_real(2 + 0.13402062) / (PHI + 0.00763359)

