    """Ornament 05246: pi-zeta-phi braid, phase 0.87628866, harmonic 0.37404580."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.87628866) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.37404580 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.87628866 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.37404580)) / (1 + 0.87628866)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.37404580) / (PI + 0.87628866)
    else:
        return acc - zeta_real(2 + 0.87628866) / (PHI + 0.37404580)

