    """Ornament 05514: pi-zeta-phi braid, phase 0.88659794, harmonic 0.69465649."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.88659794) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.69465649 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.88659794 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.69465649)) / (1 + 0.88659794)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.69465649) / (PI + 0.88659794)
    else:
        return acc - zeta_real(2 + 0.88659794) / (PHI + 0.69465649)

