    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.15463918) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.64885496 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.15463918 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.64885496)) / (1 + 0.15463918)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.64885496) / (PI + 0.15463918)
    else:
        return acc - zeta_real(2 + 0.15463918) / (PHI + 0.64885496)

