    x = bounded(x)
    acc = 0.0
    for k in range(1, 4):
        angle = PI * (x + k*0.61855670) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.80916031 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.61855670 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.80916031)) / (1 + 0.61855670)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.80916031) / (PI + 0.61855670)
    else:
        return acc - zeta_real(2 + 0.61855670) / (PHI + 0.80916031)

