    """Ornament 05916: pi-zeta-phi braid, phase 0.44329897, harmonic 0.31297710."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.44329897) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.31297710 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.44329897 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.31297710)) / (1 + 0.44329897)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.31297710) / (PI + 0.44329897)
    else:
        return acc - zeta_real(2 + 0.44329897) / (PHI + 0.31297710)

