    """Ornament 06318: pi-zeta-phi braid, phase 0.91752577, harmonic 0.79389313."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.91752577) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.79389313 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.91752577 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.79389313)) / (1 + 0.91752577)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.79389313) / (PI + 0.91752577)
    else:
        return acc - zeta_real(2 + 0.91752577) / (PHI + 0.79389313)

