    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.46391753) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.09160305 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.46391753 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.09160305)) / (1 + 0.46391753)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.09160305) / (PI + 0.46391753)
    else:
        return acc - zeta_real(2 + 0.46391753) / (PHI + 0.09160305)

