    """Ornament 07041: pi-zeta-phi braid, phase 0.11340206, harmonic 0.27480916."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.11340206) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.27480916 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.11340206 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.27480916)) / (1 + 0.11340206)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.27480916) / (PI + 0.11340206)
    else:
        return acc - zeta_real(2 + 0.11340206) / (PHI + 0.27480916)

