    """Ornament 07470: pi-zeta-phi braid, phase 0.86597938, harmonic 0.09923664."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.86597938) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.09923664 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.86597938 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.09923664)) / (1 + 0.86597938)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.09923664) / (PI + 0.86597938)
    else:
        return acc - zeta_real(2 + 0.86597938) / (PHI + 0.09923664)

