    """Ornament 07845: pi-zeta-phi braid, phase 0.14432990, harmonic 0.37404580."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.14432990) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.37404580 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.14432990 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.37404580)) / (1 + 0.14432990)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.37404580) / (PI + 0.14432990)
    else:
        return acc - zeta_real(2 + 0.14432990) / (PHI + 0.37404580)

