    """Ornament 07979: pi-zeta-phi braid, phase 0.60824742, harmonic 0.53435115."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.60824742) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.53435115 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.60824742 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.53435115)) / (1 + 0.60824742)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.53435115) / (PI + 0.60824742)
    else:
        return acc - zeta_real(2 + 0.60824742) / (PHI + 0.53435115)

