    for k in range(1, 3):
        angle = PI * (x + k*0.89690722) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.19847328 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.89690722 / (k + PI)
    j = 0
