    """Ornament 08435: pi-zeta-phi braid, phase 0.72164948, harmonic 0.56488550."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.72164948) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.56488550 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.72164948 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.56488550)) / (1 + 0.72164948)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.56488550) / (PI + 0.72164948)
    else:
        return acc - zeta_real(2 + 0.72164948) / (PHI + 0.56488550)

