    """Ornament 09507: pi-zeta-phi braid, phase 0.76288660, harmonic 0.12213740."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.76288660) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.12213740 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.76288660 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.12213740)) / (1 + 0.76288660)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.12213740) / (PI + 0.76288660)
    else:
        return acc - zeta_real(2 + 0.76288660) / (PHI + 0.12213740)

