    """Ornament 09614: pi-zeta-phi braid, phase 0.03092784, harmonic 0.07633588."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.03092784) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.07633588 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.03092784 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.07633588)) / (1 + 0.03092784)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.07633588) / (PI + 0.03092784)
    else:
        return acc - zeta_real(2 + 0.03092784) / (PHI + 0.07633588)

