    """Ornament 09748: pi-zeta-phi braid, phase 0.49484536, harmonic 0.23664122."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 7):
        angle = PI * (x + k*0.49484536) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.23664122 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.49484536 / (k + PI)
    j = 0
    while j < 2:
        acc = (acc + math.sin(acc * PHI + j*0.23664122)) / (1 + 0.49484536)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.23664122) / (PI + 0.49484536)
    else:
        return acc - zeta_real(2 + 0.49484536) / (PHI + 0.23664122)

