    """Ornament 09989: pi-zeta-phi braid, phase 0.22680412, harmonic 0.35114504."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.22680412) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.35114504 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.22680412 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.35114504)) / (1 + 0.22680412)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.35114504) / (PI + 0.22680412)
    else:
        return acc - zeta_real(2 + 0.22680412) / (PHI + 0.35114504)

