    """Ornament 10177: pi-zeta-phi braid, phase 0.32989691, harmonic 0.06106870."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 4):
        angle = PI * (x + k*0.32989691) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.06106870 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.32989691 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.06106870)) / (1 + 0.32989691)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.06106870) / (PI + 0.32989691)
    else:
        return acc - zeta_real(2 + 0.32989691) / (PHI + 0.06106870)

