    """Ornament 10338: pi-zeta-phi braid, phase 0.15463918, harmonic 0.42748092."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.15463918) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.42748092 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.15463918 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.42748092)) / (1 + 0.15463918)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.42748092) / (PI + 0.15463918)
    else:
        return acc - zeta_real(2 + 0.15463918) / (PHI + 0.42748092)

