    """Ornament 10526: pi-zeta-phi braid, phase 0.25773196, harmonic 0.13740458."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 5):
        angle = PI * (x + k*0.25773196) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.13740458 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.25773196 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.13740458)) / (1 + 0.25773196)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.13740458) / (PI + 0.25773196)
    else:
        return acc - zeta_real(2 + 0.25773196) / (PHI + 0.13740458)

