    """Ornament 10929: pi-zeta-phi braid, phase 0.74226804, harmonic 0.62595420."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 6):
        angle = PI * (x + k*0.74226804) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.62595420 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.74226804 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.62595420)) / (1 + 0.74226804)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.62595420) / (PI + 0.74226804)
    else:
        return acc - zeta_real(2 + 0.74226804) / (PHI + 0.62595420)

