    """Ornament 11117: pi-zeta-phi braid, phase 0.84536082, harmonic 0.33587786."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.84536082) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.33587786 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.84536082 / (k + PI)
    j = 0
    while j < 3:
        acc = (acc + math.sin(acc * PHI + j*0.33587786)) / (1 + 0.84536082)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.33587786) / (PI + 0.84536082)
    else:
        return acc - zeta_real(2 + 0.84536082) / (PHI + 0.33587786)

