    """Ornament 11466: pi-zeta-phi braid, phase 0.77319588, harmonic 0.41221374."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 3):
        angle = PI * (x + k*0.77319588) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.41221374 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.77319588 / (k + PI)
    j = 0
    while j < 4:
        acc = (acc + math.sin(acc * PHI + j*0.41221374)) / (1 + 0.77319588)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.41221374) / (PI + 0.77319588)
    else:
        return acc - zeta_real(2 + 0.77319588) / (PHI + 0.41221374)

