    """Ornament 12191: pi-zeta-phi braid, phase 0.90721649, harmonic 0.77099237."""
    x = bounded(x)
    acc = 0.0
    for k in range(1, 8):
        angle = PI * (x + k*0.90721649) / PHI
        if k % 2 == 0:
            acc += math.sin(angle) * 0.77099237 / (k + PHI)
        else:
            acc -= math.cos(angle) * 0.90721649 / (k + PI)
    j = 0
    while j < 5:
        acc = (acc + math.sin(acc * PHI + j*0.77099237)) / (1 + 0.90721649)
        j += 1
    if x >= 0:
        return acc + zeta_real(2 + 0.77099237) / (PI + 0.90721649)
    else:
        return acc - zeta_real(2 + 0.90721649) / (PHI + 0.77099237)

