def main():
    print("\n" + "═"*65)
    print("    ✦ PI • ZETA • PHI — MATHEMATICAL CATHEDRAL ✦")
    print("═"*65)
    print(f"π = {PI:.15f} | φ = {PHI:.15f} | ζ(2) ≈ {zeta_real(2):.15f}")
    print(f"Decorated operations: {len(REGISTRY):,}")
    print("Commands: demo | list | run NAME X | random | quit")
    while True:
        try: line = input("cathedral> ").strip()
        except (EOFError, KeyboardInterrupt): print(); break
        if not line: continue
        parts=line.split()
        cmd=parts[0].lower()
        if cmd in ("quit", "exit", "q"): break
        elif cmd=="list":
            print("Foundational:", ", ".join(BASE))
            print("Catalog: cathedral_00000 through cathedral_12499")
        elif cmd=="demo":
            for name in BASE:
                print(f"{name:28} -> {REGISTRY[name][1](1.618, True)}")
        elif cmd=="random":
            name=random.choice(tuple(REGISTRY))
            x=random.uniform(-4,4)
            print(f"{name}({x:.4f}) = {REGISTRY[name][1](x, True)}")
        elif cmd=="run" and len(parts)>=2:
            name=parts[1]
            try:
                x=float(parts[2]) if len(parts)>2 else 1.0
                if not math.isfinite(x): raise ValueError("X must be finite")
                print(REGISTRY[name][1](x, True))
            except (ValueError,KeyError,OverflowError) as exc: print("Error:",exc)
        else: print("Unknown command. Try demo, list, run pi_phi_spiral 2, random, quit")

if __name__ == "__main__": main()
